export function setupGalleryChat({getGuest,toast,stored=()=>({}),save=()=>true}){
 const $=id=>document.getElementById(id),threads=new Map();let active=null;
 const button=document.createElement('button');button.id='chatNotifications';button.className='pill chat-notifications';button.setAttribute('aria-label','Chat notifications, no unread messages');button.innerHTML='<i class="hgi-stroke hgi-message-01" aria-hidden="true"></i><span class="chat-label">Chats</span><span class="chat-count" hidden></span>';document.querySelector('.hud').append(button);
 const inbox=document.createElement('dialog');inbox.id='chatInbox';inbox.innerHTML='<div class="panel"><button class="close" aria-label="Close chat inbox">×</button><div class="eyebrow">GALLERY CONVERSATIONS · DEMO</div><h2>Your chats</h2><p class="note">Visitor and artist replies are simulated. Conversations last for this visit; nobody is connected live.</p><div id="chatThreads"></div></div>';document.body.append(inbox);inbox.querySelector('.close').onclick=()=>inbox.close();
 function badge(){const count=[...threads.values()].reduce((sum,t)=>sum+t.unread,0),counter=button.querySelector('.chat-count');counter.hidden=!count;counter.textContent=String(count);button.setAttribute('aria-label',`Chat notifications, ${count} unread message${count===1?'':'s'}`)}
 function render(){if(!active)return;$('chatName').textContent=active.work.artist;$('chatSubtitle').textContent='About '+active.work.name+' · simulated conversation';$('messages').replaceChildren();for(const entry of active.messages){const row=document.createElement('div');row.className='message'+(entry.you?' you':'');const author=document.createElement('small');author.textContent=entry.author;row.append(author,document.createTextNode(entry.body));$('messages').append(row)}$('messages').scrollTop=$('messages').scrollHeight}
 function openThread(thread){inbox.close();active=thread;thread.unread=0;badge();render();$('chatInput').value='';$('chatInput').disabled=thread.blocked;block.textContent=thread.blocked?'Unblock conversation':'Block conversation';$('chat').showModal()}
 function showInbox(){const list=$('chatThreads');list.replaceChildren();if(!threads.size){const empty=document.createElement('p');empty.textContent='No conversations yet. Open an artwork or approach a demo visitor to start one.';list.append(empty)}for(const thread of threads.values()){const row=document.createElement('button');row.className='btn collection-work';row.textContent=thread.work.artist+' · '+thread.work.name+(thread.blocked?' · blocked':'')+(thread.pending?' · invitation':thread.unread?` · ${thread.unread} unread`:'');row.onclick=()=>{if(thread.pending){thread.pending=false;thread.messages.push({author:getGuest().name,body:'Demo invitation accepted.',you:true})}openThread(thread)};list.append(row);if(thread.pending){const decline=document.createElement('button');decline.className='btn';decline.textContent='Decline '+thread.work.artist+' invitation';decline.onclick=()=>{threads.delete(thread.key);badge();inbox.close();showInbox()};list.append(decline)}}inbox.showModal()}
 button.onclick=showInbox;
  const inboxBack=document.createElement('button');inboxBack.type='button';inboxBack.className='btn dialog-back';inboxBack.textContent='← Back to gallery';inboxBack.onclick=()=>inbox.close();inbox.querySelector('.panel').prepend(inboxBack);
  const chatBack=document.createElement('button');chatBack.type='button';chatBack.className='btn dialog-back';chatBack.textContent='← Back to chats';chatBack.onclick=()=>{$('chat').close();showInbox()};$('chat').querySelector('.panel').prepend(chatBack);
 const preferences=document.createElement('label');preferences.className='chat-preference';const invitations=document.createElement('input');invitations.type='checkbox';invitations.checked=stored('anansiChatPreferences',{}).allowInvitations!==false;invitations.onchange=()=>save('anansiChatPreferences',{allowInvitations:invitations.checked});preferences.append(invitations,document.createTextNode(' Allow guest chat invitations (demo preference)'));inbox.querySelector('.panel').append(preferences);
 const testInvite=document.createElement('button');testInvite.className='btn';testInvite.textContent='Try an incoming demo invitation';testInvite.onclick=()=>{if(!invitations.checked){toast('Chat invitations are disabled.');return}const work={id:'demo-incoming',artist:'Demo visitor · Mira',name:'Guest conversation',guest:true};const key='guest:'+work.id;if(threads.has(key)){toast('That demo conversation is already in your inbox.');return}const thread={key,work,messages:[{author:work.artist,body:'Would you like to discuss the exhibition? This is a fictional visitor.'}],unread:1,pending:true};threads.set(key,thread);badge();inbox.close();toast('Demo invitation received. Open Chats to accept or decline.')};inbox.querySelector('.panel').append(testInvite);
 const controls=document.createElement('div');controls.className='actions';const block=document.createElement('button');block.type='button';block.className='btn';block.textContent='Block conversation';block.onclick=()=>{if(!active)return;active.blocked=!active.blocked;block.textContent=active.blocked?'Unblock conversation':'Block conversation';$('chatInput').disabled=active.blocked;toast(active.blocked?'Conversation blocked for this demo visit.':'Conversation unblocked.')};const report=document.createElement('button');report.type='button';report.className='btn';report.textContent='Report conversation';report.onclick=()=>{if(!active)return;const reports=stored('anansiDemoReports',[]);reports.push({id:crypto.randomUUID(),participant:active.work.artist,createdAt:new Date().toISOString(),demo:true});if(save('anansiDemoReports',reports))toast('Demo report saved locally. No moderation service receives it yet.')};controls.append(block,report);$('chat').querySelector('.panel').append(controls);
 function receive(thread,body){if(thread.blocked)return;thread.messages.push({author:thread.work.artist,body});if(active===thread&&$('chat').open){render()}else{thread.unread++;badge();toast('New demo message. Open the chat icon when you’re ready.')}}
 function start(work){const key=(work.guest?'guest:':'artist:')+(work.guest?work.id:work.artistId||work.artist);let thread=threads.get(key);if(!thread){thread={key,work,messages:[],unread:0};threads.set(key,thread);receive(thread,work.guest?'Your demo chat invitation was accepted. This visitor is fictional.':'Welcome! Ask me about '+work.name+'. This is a simulated artist conversation; no real artist is connected.')}else toast('Your conversation is in the chat icon.');badge()}
 $('closeChat').onclick=()=>$('chat').close();
 $('chatForm').onsubmit=event=>{event.preventDefault();const body=$('chatInput').value.trim();if(!body||!active||active.blocked)return;const thread=active;thread.messages.push({author:getGuest().name,body,you:true});$('chatInput').value='';render();setTimeout(()=>receive(thread,'Thank you for exploring '+thread.work.name+'. This reply is simulated; no message was sent to a real person.'),800)};
 badge();return {start};
}
